create table if not exists players(player_id uuid primary key, username text unique not null, password_hash text not null);
create table if not exists sessions(id bigserial primary key, player_id uuid references players, token_hash text unique not null, created_at timestamptz default now(), expires_at timestamptz not null, revoked_at timestamptz);
create table if not exists tickets(token_hash text primary key, player_id uuid references players, session_hash text not null, room_id text not null, preset_id text not null, resolved_config_hash text not null, protocol_version int not null, gameplay_content_hash text not null, expires_at timestamptz not null, redeemed_at timestamptz);
create index if not exists sessions_player on sessions(player_id,created_at desc);
create table if not exists rooms(room_id text primary key, host text not null, port int not null, protocol_version int not null, gameplay_content_hash text not null, resolved_config_hash text not null, capacity int not null check(capacity between 1 and 8), generation int not null, status text not null, used_players int not null default 0, last_heartbeat timestamptz not null);
create table if not exists room_reservations(room_id text references rooms(room_id) on delete cascade, player_id uuid references players(player_id) on delete cascade, created_at timestamptz default now(), released_at timestamptz, primary key(room_id,player_id));
create unique index if not exists active_player_reservation on room_reservations(player_id) where released_at is null;
create table if not exists player_progress(player_id uuid primary key references players(player_id) on delete cascade, schema_version int not null default 1, revision bigint not null default 0, inventory jsonb not null default '{}'::jsonb, equipment jsonb not null default '{}'::jsonb, unlocks jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create table if not exists active_player_sessions(player_id uuid primary key references players(player_id) on delete cascade, fencing_token bigint not null, room_id text not null, lease_expires_at timestamptz not null);
create table if not exists progress_operations(player_id uuid not null references players(player_id) on delete cascade, operation_id text not null, payload_hash text not null, status text not null, result jsonb not null default '{}'::jsonb, revision bigint not null, created_at timestamptz not null default now(), primary key(player_id, operation_id));
